// Mensagem de alerta para quem opera. So metadados: nada de telefone do
// cliente, texto da conversa, transcricao ou token. Quem precisa do detalhe
// abre a execucao no n8n pelo id.
const OPERADOR = 'CONFIGURAR_NO_N8N'; // telefone do operador, com pais e DDD e sem sinais
const EVOLUTION_BASE = 'CONFIGURAR_NO_N8N';
const INSTANCIA_ALERTA = 'CONFIGURAR_NO_N8N';

const e = $input.first().json || {};
const execucao = e.execution || {};
// Erro no proprio no de gatilho vem noutra forma: o n8n entrega
// `{ trigger: { error, mode }, workflow }` - sem `execution` e SEM nome de no.
// Quem procurar `trigger.name` aqui nao vai achar: esse campo nao existe.
const gatilho = e.trigger || {};
const fluxo = e.workflow || {};
const erro = execucao.error || gatilho.error || {};

// O texto do erro NAO sai daqui. Ele carrega o que estava em transito quando a
// execucao caiu: a saida do modelo, o corpo que a Evolution recusou, a linha do
// banco. Isso ja foi visto levar nome, telefone e condicao de saude do cliente -
// e o destino e um WhatsApp externo, fora do controle do assinante. Sai a
// CLASSE do erro, que basta para triagem; o detalhe fica na execucao, que so
// quem tem acesso ao n8n abre.
const CLASSES = ['ETIMEDOUT', 'ECONNREFUSED', 'ECONNRESET', 'ENOTFOUND', 'EAI_AGAIN',
  'timeout', '401', '403', '404', '409', '422', '429', '500', '502', '503', '504',
  // A Evolution abre a mensagem com estes prefixos; sem eles o operador recebia
  // "sem classificacao" no erro mais comum de todos.
  'Bad request', 'Request failed with status code', 'Unauthorized', 'Forbidden',
  'Not Found', 'Connection Closed', 'socket hang up'];
// Nome de classe e identificador, nunca frase: `erro.name` e o unico campo livre
// que sobrou e sai daqui para um WhatsApp externo.
const NOME_DE_CLASSE = /^[A-Za-z][A-Za-z0-9_]{2,39}$/;
const textoDoErro = String(erro.message || '');
const nome = String(erro.name || '').trim();
const classe = (NOME_DE_CLASSE.test(nome) ? nome : '')
  || CLASSES.find((c) => textoDoErro.includes(c))
  || 'sem classificacao';
const configurado = ![OPERADOR, EVOLUTION_BASE, INSTANCIA_ALERTA]
  .some((v) => !v || v === 'CONFIGURAR_NO_N8N');

const texto = [
  'Agenda Magnetica: uma execucao falhou.',
  'Fluxo: ' + (fluxo.name || 'desconhecido'),
  'No: ' + (execucao.lastNodeExecuted
    || (gatilho.error ? 'gatilho do fluxo (' + (gatilho.mode || 'sem modo') + ')' : 'desconhecido')),
  'Execucao: ' + (execucao.id || 'sem id'),
  'Erro: ' + classe,
].join('\n');

return [{ json: { configurado, numero: OPERADOR, evolution_base: EVOLUTION_BASE,
                  instancia: INSTANCIA_ALERTA, texto } }];

// Chegar aqui significa que uma execucao falhou E o alerta nao pode ser
// enviado, porque o operador, a origem da Evolution ou a instancia ainda
// estao com o marcador de configuracao. Encerrar calado esconderia as duas
// falhas de uma vez, entao este no lanca: a execucao fica salva.
throw new Error('alerta nao enviado: configure OPERADOR, EVOLUTION_BASE e INSTANCIA_ALERTA no no "montar alerta"');

// A Evolution recusou o envio do alerta — possivelmente a mesma queda que
// causou a falha original. Lancar deixa esta execucao salva no historico,
// que passa a ser o unico registro de que alguem deveria ter sido avisado.
throw new Error('falha ao enviar o alerta pela Evolution');
